using System;using System.Drawing;using System.Text;namespace Mapping{    /// <summary>    ///     /// </summary>    public class BinCodeMap    {        private readonly ushort[,] _binCodes;        private readonly BinDefinitionCollection _binDefinitions;        public BinCodeMap(BinCodeType binType, ushort nullBin, MapType mapType, ushort[,] binCodes)        {            if (binCodes is null)            {                throw new ArgumentNullException(nameof(binCodes), "binCodes must not been null");            }            if (binCodes.GetLength(0) == 0 || binCodes.GetLength(1) == 0)            {                throw new ArgumentOutOfRangeException(nameof(binCodes), "The dimension of binCodes must not been zero");            }            this.BinType = binType;            this.NullBin = nullBin;            this.MapType = mapType;            this._binCodes = binCodes;            this._binDefinitions = new BinDefinitionCollection(this);        }        public BinDefinition this[ushort binCode]        {            get            {                return this._binDefinitions[binCode];            }        }        /// <summary>        /// The format in which the each device will be represented.        /// </summary>        public BinCodeType BinType { get; private set; }        /// <summary>        /// Code to indicate no device or not measured device in BinCode.Values.        /// It should be represented according to <see cref="BinCodeType"/>.        /// </summary>        public ushort NullBin { get; private set; }        public MapType MapType { get; private set; }        public int RowCount        {            get => this._binCodes.GetLength(0);        }        public int ColumnCount        {            get => this._binCodes.GetLength(1);        }        public BinDefinitionCollection BinDefinitions => this._binDefinitions;    }}